// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address sender, address to, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(to != address(0));
        vm.assume(sender != to);
        vm.prank(c.owner());
        c.mintToken(sender, amount);
        uint256 senderBefore = c.balanceOf(sender);
        uint256 toBefore = c.balanceOf(to);
        vm.prank(sender);
        c.transfer(to, amount);
        uint256 senderAfter = c.balanceOf(sender);
        uint256 toAfter = c.balanceOf(to);
        assertTrue(senderBefore - senderAfter == amount && toAfter - toBefore == amount);
    }
}
